import os,runpy,sys,json
from pathlib import Path
def load(p):
 with p.open('rb') as f:b=f.read(65537)
 if len(b)>65536:raise ValueError('MindIE metadata exceeds its byte bound')
 v=json.loads(b)
 if not isinstance(v,dict):raise ValueError('MindIE metadata must be an object')
 return v
home=Path(os.environ.get('CODEX_HOME',str(Path.home()/'.codex')))
data=Path(os.environ.get('PLUGIN_DATA',str(home/'plugins/data'/'mindie-agent-mindie-agent')))
config=Path(os.environ.get('MINDIE_AGENT_CONFIG',str(Path.home()/'.config/mindie-agent/codex.json'))).expanduser().absolute()
seed='0.1.31'
cands=[]
root=os.environ.get('PLUGIN_ROOT')
if root:cands.append(Path(root)/'scripts'/'hook_launcher.py')
cands.append(data/'hook_launcher.py')
if seed:cands.append(data/'releases'/seed/'hook_launcher.py')
if config.is_file():
 a=load(config);v=a.get('product_validation',{}).get('native_version')
 if a.get('component_release'):cands.append(Path(a['component_release'])/'hook_launcher.py')
 elif isinstance(v,str):cands.append(data/'releases'/v/'hook_launcher.py')
cands.append(Path(os.environ.get('PLUGIN_ROOT',str(home/'plugins/cache'/'mindie-agent'/'mindie-agent'/(seed or 'unprepared'))))/'scripts'/'hook_launcher.py')
p=next((c for c in cands if c.is_file()),None)
if p is None:raise RuntimeError('MindIE launcher is unavailable')
sys.argv=[str(p),*sys.argv[1:]]
runpy.run_path(str(p),run_name='__main__')

